import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.vLhlLNVn.js";const h=JSON.parse('{"title":"版本与迁移","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compatibility.md","filePath":"guide/compatibility.md"}'),i={name:"guide/compatibility.md"};function r(c,t,n,l,s,p){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="版本与迁移" tabindex="-1">版本与迁移 <a class="header-anchor" href="#版本与迁移" aria-label="Permalink to &quot;版本与迁移&quot;">​</a></h1><h2 id="版本基线" tabindex="-1">版本基线 <a class="header-anchor" href="#版本基线" aria-label="Permalink to &quot;版本基线&quot;">​</a></h2><p>包版本为 <strong>0.1.0</strong>（见 <code>package.json</code> 的 <code>version</code> 字段）；文档 JSON 的格式版本为 <strong>&#39;1.0&#39;</strong>（常量 <code>DOCUMENT_VERSION</code>，从 <code>@printstack/print-studio/core</code> 导出）。两者相互独立：包版本随功能发布演进，文档格式版本只在文档结构变化时调整。</p><h2 id="兼容范围" tabindex="-1">兼容范围 <a class="header-anchor" href="#兼容范围" aria-label="Permalink to &quot;兼容范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>模块格式</td><td>纯 ESM，经公共入口（<code>@printstack/print-studio</code> / <code>@printstack/print-studio/core</code> / <code>@printstack/print-studio/designer</code> / <code>@printstack/print-studio/runtime</code> / <code>@printstack/print-studio/vue</code>）导入，不提供 CommonJS 接入</td></tr><tr><td>Vue</td><td><code>^3.5.0</code>；宿主与库需共享同一份兼容的 Vue 实例</td></tr><tr><td>界面依赖</td><td>pinia、vue-i18n、tdesign-vue-next、tdesign-icons-vue-next 随包自动安装，无需宿主额外接入</td></tr><tr><td>浏览器</td><td>输出与设计器使用标准 DOM、Canvas、字体与下载能力；系统打印行为由浏览器决定，建议按目标浏览器实际验收</td></tr><tr><td>移动端</td><td>可打开文档；设计器需要足够的容器宽高</td></tr><tr><td>Node.js / SSR</td><td>模板渲染依赖浏览器环境，不在服务端直接运行</td></tr><tr><td>PDF / 图片 / 字体</td><td>浏览器资源加载与跨域策略参与输出结果，需用实际资源验证</td></tr></tbody></table><h2 id="文档格式与加载行为" tabindex="-1">文档格式与加载行为 <a class="header-anchor" href="#文档格式与加载行为" aria-label="Permalink to &quot;文档格式与加载行为&quot;">​</a></h2><p><code>deserializeDocument</code>（<code>@printstack/print-studio/core</code>）对传入 JSON 宽容处理：</p><ul><li>未知元素类型被剔除，类型记录在返回值 <code>skippedTypes</code> 中；</li><li>缺少页面的文档补空白模板，悬空的 <code>templateId</code> 置空；</li><li>旧字段 <code>repeatOnEveryPage</code> 不再有效，加载时被忽略。</li></ul><p>需要严格校验时，<code>createPrintStudio({ strictInitialDocument: true })</code> 会在初始文档含未知类型时抛出 <code>document.unsupported-elements</code>，不静默剔除。</p><h2 id="升级建议" tabindex="-1">升级建议 <a class="header-anchor" href="#升级建议" aria-label="Permalink to &quot;升级建议&quot;">​</a></h2><ul><li>升级包版本前导出模板 JSON 备份，保留数据源示例数据。</li><li>升级后验证：加载既有文档、编辑、保存恢复、HTML / PDF 输出与预览清理。</li><li>元素属性在加载时会做兼容归一化（补全缺省、迁移旧字段），且该过程幂等；不要假设包版本更新会自动改写业务字段。</li><li>设计器与输出端注册的自定义元素定义需保持一致，加载文档前两侧都完成注册。</li><li>字体在测量与分页前加载，实际字体可能改变换行与页数；资源加载与超时行为见<a href="./../reference/output.html#字体与资源">字体与资源</a>。</li></ul>',11)])])}const m=e(i,[["render",r]]);export{h as __pageData,m as default};
